import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

fused_sub_mish_source = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <math.h>

__global__ void fused_sub_mish_kernel(const float* __restrict__ inp,
                                      float* __restrict__ out,
                                      const int size,
                                      const float sub_val1,
                                      const float sub_val2) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < size) {
        float val = inp[idx] - sub_val1 - sub_val2;
        // mish: x * tanh(softplus(x)) = x * tanh(log(1 + exp(x)))
        float sp = logf(1.0f + expf(val));
        float mish_val = val * tanhf(sp);
        out[idx] = mish_val;
    }
}

torch::Tensor fused_sub_mish_cuda(torch::Tensor x,
                                  float sub_val1,
                                  float sub_val2) {
    auto out = torch::empty_like(x);
    int size = x.numel();

    const int block_size = 256;
    const int grid_size = (size + block_size - 1) / block_size;

    fused_sub_mish_kernel<<<grid_size, block_size>>>(
        x.data_ptr<float>(),
        out.data_ptr<float>(),
        size,
        sub_val1,
        sub_val2
    );

    return out;
}
"""

fused_sub_mish_cpp_source = r"""
torch::Tensor fused_sub_mish_cuda(torch::Tensor x,
                                  float sub_val1,
                                  float sub_val2);
"""

fused_sub_mish = load_inline(
    name="fused_sub_mish",
    cpp_sources=fused_sub_mish_cpp_source,
    cuda_sources=fused_sub_mish_source,
    functions=["fused_sub_mish_cuda"],
    verbose=False,
)

class ModelNew(nn.Module):
    """
    Optimized Model that fuses the subtracts and Mish activation into a single custom CUDA kernel.
    """
    def __init__(self, in_channels, out_channels, kernel_size, subtract_value_1, subtract_value_2):
        super(ModelNew, self).__init__()
        self.conv = nn.Conv2d(in_channels, out_channels, kernel_size)
        self.subtract_value_1 = subtract_value_1
        self.subtract_value_2 = subtract_value_2
        self.fused_sub_mish = fused_sub_mish

    def forward(self, x):
        x = self.conv(x)
        x = self.fused_sub_mish.fused_sub_mish_cuda(
            x, self.subtract_value_1, self.subtract_value_2
        )
        return x
